UPDATE product_translations SET name = 'ViMai Tokutei Taxi', tagline = '特定技能1号（タクシー）の学習アプリ', description = '外国人が日本の特定技能1号・タクシー分野の試験勉強と演習を行うためのアプリです。CBT形式の練習、模擬問題、誤答の見直し、学習のヒント、日本語とベトナム語、振り仮名、解説を備えています。', long_description = '試験の合格を保証するものではありません。出題形式に慣れることと、間違えた箇所を見直すことを目的とした学習ツールです。', target_audience = '日本でタクシー分野の特定技能1号を目指す外国人学習者。', features = '["CBT形式の練習", "模擬問題", "誤答の見直し", "学習のヒント", "日本語・ベトナム語", "振り仮名", "わかりやすい解説"]' WHERE product_id = '00000000-0000-0000-0000-000000000001' AND locale = 'ja';
UPDATE product_translations SET name = 'ViMai Tokutei Taxi', tagline = 'Ứng dụng luyện thi 特定技能1号 – Taxi', description = 'Ứng dụng dành cho người nước ngoài học và luyện thi 特定技能1号 ngành Taxi tại Nhật. Có luyện CBT, câu hỏi mô phỏng, ôn lại câu sai, mẹo làm bài, hỗ trợ tiếng Nhật và tiếng Việt, Furigana và phần giải thích.', long_description = 'Công cụ học tập để làm quen dạng đề và rà soát chỗ sai. Không cam kết đậu kỳ thi.', target_audience = 'Người nước ngoài tại Nhật đang chuẩn bị thi 特定技能1号 ngành Taxi.', features = '["Luyện dạng CBT", "Câu hỏi thi thử", "Ôn lại câu sai", "Mẹo làm bài", "Hỗ trợ tiếng Nhật và tiếng Việt", "Furigana", "Giải thích rõ ràng"]' WHERE product_id = '00000000-0000-0000-0000-000000000001' AND locale = 'vi';
UPDATE product_translations SET name = 'ViMai Tokutei Taxi', tagline = 'Study app for Specified Skilled Worker (i) Taxi', description = 'An app for foreigners studying and practicing for Japan’s Specified Skilled Worker (i) Taxi field. It includes CBT-style practice, mock questions, mistake review, study tips, Japanese and Vietnamese support, furigana, and explanations.', long_description = 'A study tool for exam format and review. It does not guarantee a passing result.', target_audience = 'Foreign residents in Japan preparing for Specified Skilled Worker (i) Taxi.', features = '["CBT-style practice", "Mock questions", "Mistake review", "Study tips", "Japanese and Vietnamese support", "Furigana", "Clear explanations"]' WHERE product_id = '00000000-0000-0000-0000-000000000001' AND locale = 'en';

