UPDATE product_translations SET name = 'ViMai Transport', tagline = '特定技能（自動車運送・トラック）の学習アプリ', description = '特定技能の運送・トラック分野に取り組む外国人向けの学習アプリです。対象者、学習の目的、模擬試験、日本語サポート、振り仮名、わかりやすい解説、日本での就労の方向性を整理して学べます。', long_description = '試験や就労の結果を保証するものではありません。学習範囲と出題形式を把握するためのツールです。', target_audience = '日本の特定技能・自動車運送業（トラック等）を目指す外国人学習者。', features = '["運送分野の学習目的が明確", "模擬試験", "日本語サポート", "振り仮名", "わかりやすい解説", "日本での就労に向けた方向づけ"]' WHERE product_id = '00000000-0000-0000-0000-000000000002' AND locale = 'ja';
