UPDATE product_translations SET name = 'ViMai Transport', tagline = 'Study app for Specified Skilled Worker transport / trucking', description = 'An app for foreigners studying the Specified Skilled Worker transport and trucking field. It highlights the audience, study purpose, practice exams, Japanese support, furigana, clear explanations, and career orientation in Japan.', long_description = 'A tool for understanding the study scope and exam format. It does not guarantee exam or employment outcomes.', target_audience = 'Foreign learners preparing for Specified Skilled Worker automobile transport / trucking in Japan.', features = '["Clear study purpose for transport work", "Practice exams", "Japanese-language support", "Furigana", "Clear explanations", "Career orientation in Japan"]' WHERE product_id = '00000000-0000-0000-0000-000000000002' AND locale = 'en';

