UPDATE product_translations SET name = 'ViMai Seibi', tagline = 'Study app for Seibi 3kyu (Class 3 automobile mechanic)', description = 'An app for studying Seibi 3kyu. It highlights the audience, curriculum scope, support for foreign learners, structured study, and the product’s strengths.', long_description = 'A tool for organizing written-exam study. It does not guarantee a passing result.', target_audience = 'Foreign learners and Japanese-language learners studying Class 3 automobile mechanic theory.', features = '["Curriculum aligned with Seibi 3kyu", "Support for foreign learners", "Structured learning path", "Written-exam knowledge organized clearly"]' WHERE product_id = '00000000-0000-0000-0000-000000000003' AND locale = 'en';

